1	import java.util.ArrayList;
2	import java.util.Iterator;
3	import java.util.List;
4	
5	/**
6	 * A simple predator-prey simulator, based on a rectangular field
7	 * containing rabbits and foxes.
8	 *
9	 * @version 2022.03.02
10	 */
11	public class Simulator
12	{
13	    // Constants representing configuration information for the simulation.
14	    // The default width for the grid.
15	    private static final int DEFAULT_WIDTH = 200;
16	    // The default depth of the grid.
17	    private static final int DEFAULT_DEPTH = 200;
18	
19	    // List of organisms in the field.
20	    private List<Entity> organisms;
21	    // The current state of the field.
22	    private Field field;
23	    // The current step of the simulation.
24	    private int step;
25	    // A graphical view of the simulation.
26	    private SimulatorView view;
27	    // The current hour of the simulation.
28	    private int hour;
29	    // Indicates current state of time in the simulation.
30	    private TimeOfDay currentTime;
31	
32	    private Weather currentWeather;
33	
34	    /**
35	     * Construct a simulation field with default size.
36	     */
37	    public Simulator()
38	    {
39	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
40	    }
41	    
42	    /**
43	     * Create a simulation field with the given size.
44	     * @param depth Depth of the field. Must be greater than zero.
45	     * @param width Width of the field. Must be greater than zero.
46	     */
47	    public Simulator(int depth, int width)
48	    {
49	        if(width <= 0 || depth <= 0) {
50	            System.out.println("The dimensions must be greater than zero.");
51	            System.out.println("Using default values.");
52	            depth = DEFAULT_DEPTH;
53	            width = DEFAULT_WIDTH;
54	        }
55	        
56	        organisms = new ArrayList<>();
57	        field = new Field(depth, width);
58	
59	        // Create a view of the state of each location in the field.
60	        view = new SimulatorView(depth, width);
61	
62	        // Setup a valid starting point
63	        reset();
64	    }
65	    
66	    /**
67	     * Run the simulation from its current state for a reasonably long period,
68	     * (4000 steps).
69	     */
70	    public void runLongSimulation()
71	    {
72	        simulate(4000);
73	    }
74	    
75	    /**
76	     * Run the simulation from its current state for the given number of steps.
77	     * Stop before the given number of steps if it ceases to be viable.
78	     * @param numSteps The number of steps to run for.
79	     */
80	    public void simulate(int numSteps)
81	    {
82	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
83	            simulateOneStep();
84	            delay(5);   // uncomment this to run more slowly
85	        }
86	    }
87	    
88	    /**
89	     * Run the simulation from its current state for a single step.
90	     * Iterate over the whole field updating the state of each
91	     * fox and rabbit.
92	     */
93	    public void simulateOneStep()
94	    {
95	        step++;
96	
97	        // Provide space for newborn organisms.
98	        List<Entity> newOrganisms = new ArrayList<>();
99	        // Let all rabbits act.
100	        for(Iterator<Entity> it = organisms.iterator(); it.hasNext(); ) {
101	            Entity entity = it.next();
102	            Organism organism = (Organism) entity;
103	
104	            organism.act(newOrganisms, currentWeather, currentTime);
105	
106	            if(organism.isRemoved()) {
107	                it.remove();
108	            }
109	        }
110	               
111	        // Add the newly born foxes and rabbits to the main lists.
112	        organisms.addAll(newOrganisms);
113	
114	        int day = step/120 +1;
115	        hour = (step/5) % 24 + 1;
116	
117	
118	        view.showStatus(step, field);
119	        view.updateTimeLabel(day,hour);
120	        view.updateEnvironmentLabel(currentWeather, currentTime);
121	
122	        // every hour, generate new weather if we are done with current weather
123	        if (step % 5 == 0) {
124	            currentWeather.generate();
125	        }
126	
127	        // update time
128	        if ((hour % 4 == 0) && (step % 5 == 0)) {
129	            currentTime = currentTime.next();
130	        }
131	    }
132	
133	    public int getHour() {
134	        return hour;
135	    }
136	
137	    /**
138	     * Reset the simulation to a starting position.
139	     */
140	    public void reset()
141	    {
142	        step = 0;
143	
144	        currentTime = TimeOfDay.SUNRISE;
145	        currentWeather = new Weather(WeatherType.SUN); // make this random at start
146	
147	        organisms.clear();
148	
149	        Populator populator = new Populator(view);
150	        populator.populate(organisms, field);
151	        
152	        // Show the starting state in the view.
153	        view.showStatus(step, field);
154	    }
155	    
156	    /**
157	     * Pause for a given time.
158	     * @param millisec  The time to pause for, in milliseconds
159	     */
160	    private void delay(int millisec)
161	    {
162	        try {
163	            Thread.sleep(millisec);
164	        }
165	        catch (InterruptedException ie) {
166	            // wake up
167	        }
168	    }
169	}
