1	import java.util.List;
2	import java.util.Random;
3	
4	/**
5	 * This file is part of the Predator-Prey Simulation.
6	 *
7	 * An abstract class representing any organism in the simulation.
8	 *
9	 * @version 2022.03.02
10	 */
11	public abstract class Organism implements Entity {
12	
13	    // define fields
14	    //number of steps an organism remains for after dying but not having been eaten
15	    private static final int LIFETIME_AFTER_DEATH = 40;
16	    private boolean alive;
17	    private boolean removed;
18	    private Field field;
19	    private Location location;
20	    private int howLongDead;
21	
22	    private int age;
23	
24	    // shared random generator to generate consistent results
25	    private static final Random rand = Randomizer.getRandom();
26	
27	    /**
28	     * Constructor for an Organism in the simulation.
29	     *
30	     * @param randomAge Whether we assign this organism a random age or not.
31	     * @param field The field in which this organism resides.
32	     * @param location The location in which this organism is spawned into.
33	     */
34	    public Organism(boolean randomAge, Field field, Location location) {
35	        this.howLongDead = 0;
36	        alive = true;
37	        removed = false;
38	        this.field = field;
39	        setLocation(location);
40	
41	        if (randomAge) {
42	            age = rand.nextInt(getMaxAge());
43	        } else {
44	            age = 0;
45	        }
46	    }
47	
48	    /**
49	     * Abstract method for what an organism does, i.e. what is always run at every step.
50	     *
51	     * @param newOrganisms A list of all newborn organisms in this simulation step.
52	     * @param weather The current state of weather in the simulation.
53	     * @param time The current state of time in the simulation.
54	     */
55	    @Override
56	    abstract public void act(List<Entity> newOrganisms, Weather weather, TimeOfDay time);
57	
58	    /**
59	     * Check whether the organism is alive or not.
60	     * @return true if the organism is still alive.
61	     */
62	    protected boolean isAlive()
63	    {
64	        return alive;
65	    }
66	
67	    /**
68	     * Removes the current organism from the field.
69	     */
70	    protected void remove() {
71	        setDead();
72	        if(location != null) {
73	            field.clear(location);
74	            location = null;
75	            setField(null);
76	        }
77	        removed = true;
78	    }
79	
80	    /**
81	     * Return whether the current organism object is supposed
82	     * to be removed from the simulation.
83	     *
84	     * @return A boolean value representing if the organism has been removed or not.
85	     */
86	    public boolean isRemoved() {
87	        return removed;
88	    }
89	
90	    /**
91	     * Indicate that the organism is no longer alive.
92	     */
93	    protected void setDead()
94	    {
95	        alive = false;
96	    }
97	
98	    /**
99	     * Return the organism's location.
100	     * @return The organism's location.
101	     */
102	    protected Location getLocation()
103	    {
104	        return this.location;
105	    }
106	
107	    /**
108	     * Place the organism at the new location in the given field.
109	     * @param newLocation The organism's new location.
110	     */
111	    protected void setLocation(Location newLocation)
112	    {
113	        if(location != null) {
114	            field.clear(location);
115	        }
116	        location = newLocation;
117	        field.place(this, newLocation);
118	    }
119	
120	    /**
121	     * Set the organism's location to a null value directly.
122	     */
123	    protected void setLocationToNull() {
124	        location = null;
125	    }
126	
127	    /**
128	     * Return the organism's field.
129	     * @return The organism's field.
130	     */
131	    protected Field getField()
132	    {
133	        return this.field;
134	    }
135	
136	    /**
137	     * Getter method for the probability to breed of the organism.
138	     *
139	     * @return A double value representing the breeding probability.
140	     */
141	    abstract public double getBreedingProbability();
142	
143	    /**
144	     * Getter method for the maximum litter size of the organism's newborns.
145	     *
146	     * @return An integer value representing the maximum allowed litter size.
147	     */
148	    abstract public int getMaxLitterSize();
149	
150	    /**
151	     * Getter method for the maximum age of the organism.
152	     *
153	     * @return An integer value representing the maximum age.
154	     */
155	    abstract public int getMaxAge();
156	
157	    /**
158	     * Getter method for the age of breeding of the organism.
159	     *
160	     * @return A double value representing the breeding age.
161	     */
162	    abstract public int getBreedingAge();
163	
164	    /**
165	     * Called when breeding occurs for this organism.
166	     *
167	     * @return The number of births as a result of breeding.
168	     */
169	    protected int breed() {
170	        int births = 0;
171	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
172	            births = rand.nextInt(getMaxLitterSize()) + 1;
173	        }
174	        return births;
175	    }
176	
177	    /**
178	     * Create a new instance of this organism.
179	     * @param field The field in which the spawn will reside in.
180	     * @param location The location in which the spawn will occupy.
181	     * @return A new Organism instance.
182	     */
183	    abstract protected Organism createNewOrganism(Field field, Location location);
184	
185	    /**
186	     * Check whether or not this organism is to give birth at this step.
187	     * New births will be made into free adjacent locations.
188	     * @param newOrganisms A list to return newly born organisms.
189	     */
190	    protected void giveBirth(List<Entity> newOrganisms) {
191	        // New organisms are born into adjacent locations.
192	        // Get a list of adjacent free locations.
193	        Field field = getField();
194	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
195	        int births = breed();
196	        for(int b = 0; b < births && free.size() > 0; b++) {
197	            Location loc = free.remove(0);
198	            newOrganisms.add(createNewOrganism(field, loc));
199	        }
200	    }
201	
202	    /**
203	     * Checks all adjacent location for organisms that meet specific
204	     * breeding conditions, and returns true if it is even possible.
205	     *
206	     * @return Whether this organism can breed or not.
207	     */
208	    abstract protected boolean canBreed();
209	
210	    /**
211	     * Increase the age.
212	     * This could result in the organisms death.
213	     */
214	    protected void incrementAge()
215	    {
216	        age++;
217	
218	        if (age > getMaxAge()) {
219	            //setDead();
220	            remove();
221	        }
222	    }
223	
224	    /**
225	     * Getter method for the current age of this organism.
226	     *
227	     * @return An integer value representing age.
228	     */
229	    protected int getAge() {
230	        return this.age;
231	    }
232	
233	    /**
234	     * Setter method for the field in which this organism resides.
235	     * @param field The field where the organism is located.
236	     */
237	    protected void setField(Field field) {
238	        this.field = field;
239	    }
240	
241	    /**
242	     * Prevents overcrowding of dead animals
243	     * Remove the organism from the field after being dead for a s
244	     * specified number of steps and not being eaten.
245	     */
246	    protected void decayifDead() {
247	        this.howLongDead++;
248	        if (this.howLongDead > LIFETIME_AFTER_DEATH){
249	            remove();
250	        }
251	    }
252	}
