1	import java.util.List;
2	import java.util.Random;
3	
4	/**
5	 * This file is part of the Predator-Prey Simulation.
6	 *
7	 * An abstract animal organism present in the simulation.
8	 *
9	 * @version 2022.03.02
10	 */
11	public abstract class Animal extends Organism implements AbleToEat {
12	
13	    // define fields
14	    private final Gender gender; // gender of specific animal
15	    private boolean infected; // whether an animal has been infected or not
16	
17	    // shared random generator to generate consistent results
18	    private static final Random rand = Randomizer.getRandom();
19	
20	    /**
21	     * Constructor for an animal in the simulation.
22	     *
23	     * @param randomAge Whether the animal should have a random age or not.
24	     * @param field The field in which the animal resides.
25	     * @param location The location in which the animal spawns into.
26	     */
27	    public Animal(boolean randomAge, Field field, Location location) {
28	        super(randomAge, field, location);
29	
30	        // randomly assign male or female
31	        this.gender = Gender.getRandom();
32	        this.infected = false;
33	    }
34	
35	    /**
36	     * Abstract method for what the animal does, i.e. what is always run at every step.
37	     *
38	     * @param newAnimals A list of all newborn animals in this simulation step.
39	     * @param weather The current state of weather in the simulation.
40	     * @param time The current state of time in the simulation.
41	     */
42	    @Override
43	    abstract public void act(List<Entity> newAnimals, Weather weather, TimeOfDay time);
44	
45	    /**
46	     * Called when a consumable food item may be eaten.
47	     *
48	     * @param consumable The item to be eaten.
49	     * @return Whether the item was eaten or not.
50	     */
51	    @Override
52	    abstract public boolean eat(Consumable consumable);
53	
54	    /**
55	     * Checks all adjacent location for animals that meet specific
56	     * breeding conditions, and returns true if it is even possible.
57	     *
58	     * @return Whether this animal can breed or not.
59	     */
60	    @Override
61	    abstract protected boolean canBreed();
62	
63	    /**
64	     * Getter method returning the gender of this animal.
65	     *
66	     * @return The gender of the animal.
67	     */
68	    private Gender getGender() {
69	        return this.gender;
70	    }
71	
72	    /**
73	     * Returns if the animal is a male or not.
74	     *
75	     * @return Whether the animal's gender is male or not.
76	     */
77	    protected boolean isMale() {
78	        return getGender() == Gender.MALE;
79	    }
80	
81	    /**
82	     * Getter method returning whether the animal has been
83	     * infected or not.
84	     *
85	     * @return Whether the animal is infectious or not.
86	     */
87	    protected boolean isInfected() {
88	        return this.infected;
89	    }
90	
91	    /**
92	     * Setter method to alter the infected field of this animal
93	     * to a given boolean.
94	     *
95	     * @param infected The value the infected field should be changed to.
96	     */
97	    private void setInfected(boolean infected) {
98	        this.infected = infected;
99	    }
100	
101	    /**
102	     * Infects a given animal.
103	     *
104	     * @param animal The animal to infect.
105	     */
106	    protected void infect(Animal animal) {
107	        animal.setInfected(true);
108	    }
109	
110	    /**
111	     * Find an animal in an adjacent location for this animal to infect.
112	     *
113	     * @return The location of a nearby animal that can be infected.
114	     */
115	    protected Location findAnimalToInfect() {
116	        if (!infected) {
117	            return null;
118	        }
119	
120	        for (Location loc : getField().adjacentLocations(getLocation())) {
121	            Object organism = getField().getObjectAt(loc);
122	            if (organism instanceof Animal) {
123	                Animal animal = (Animal) organism;
124	                if (animal.isAlive() && (!animal.isInfected())) {
125	                    if (rand.nextDouble() <= 0.01) {
126	                        infect(animal);
127	                    }
128	                    return loc;
129	                }
130	            }
131	        }
132	
133	        return null;
134	    }
135	
136	    /**
137	     * Getter method to return this animal's disease spreading probability.
138	     *
139	     * @return The animal's disease spreading probability.
140	     */
141	    abstract protected double getDiseaseSpreadProbability();
142	
143	    /**
144	     * Getter method to return the probability this animal dies from disease.
145	     *
146	     * @return The animal's disease death probability.
147	     */
148	    abstract protected double getDeathByDiseaseProbability();
149	}

1	import java.util.List;
2	
3	/**
4	 * This file is part of the Predator-Prey Simulation.
5	 *
6	 * An abstract plant organism present in the simulation.
