11	 */
12	public abstract class Predator extends Animal {
13	
14	    // define fields
15	
16	    // shared random generator to generate consistent results
17	    private static final Random rand = Randomizer.getRandom();
18	
19	    private int foodLevel;
20	
21	    /**
22	     * Constructor for a predator in the simulation.
23	     *
24	     * @param foodLevel The food level of this predator.
25	     * @param randomAge Whether the predator should have a random age or not.
26	     * @param field The field in which the predator resides.
27	     * @param location The location in which the predator spawns into.
28	     */
29	    public Predator(int foodLevel, boolean randomAge, Field field, Location location) {
30	        super(randomAge, field, location);
31	
32	        this.foodLevel = foodLevel;
33	    }
34	
35	    /**
36	     * Abstract method for what the predator does, i.e. what is always run at every step.
37	     *
38	     * @param newPredators A list of all newborn predators in this simulation step.
39	     * @param weather The current state of weather in the simulation.
40	     * @param time The current state of time in the simulation.
41	     */
42	    @Override
43	    abstract public void act(List<Entity> newPredators, Weather weather, TimeOfDay time);
44	
45	    /**
46	     * Finds the nearest food source and returns its location.
47	     *
48	     * @return Location of food source.
49	     */
50	    @Override
51	    public Location findFood() {
52	        Field field = getField();
53	        List<Location> adjacent = field.adjacentLocations(getLocation());
54	        Iterator<Location> it = adjacent.iterator();
55	        while(it.hasNext()) {
56	            Location where = it.next();
57	
58	            Object animal = field.getObjectAt(where);
59	            if(animal instanceof Prey) {
60	                Prey prey = (Prey) animal;
61	                if (prey.isAlive()) {
62	                    // kills animal
63	                    prey.setDead();
64	                    // random chance to eat
65	                    boolean eaten = eat(prey);
66	
67	                    return eaten ? where : null;
68	                }
69	            }
70	        }
71	        return null;
72	    }
73	
74	    /**
75	     * Getter method to return this predator's probability of eating if food is found.
76	     *
77	     * @return The predator's eating probability.
78	     */
79	    abstract public double getEatingProbability();
80	
81	    /**
82	     * Called when a predator either eats or leaves a prey it
83	     * has killed.
84	     *
85	     * @param consumable The prey to be eaten.
86	     * @return Whether the prey has been eaten or not.
87	     */
88	    @Override
89	    public boolean eat(Consumable consumable) {
90	        if (rand.nextDouble() <= getEatingProbability()) {
91	            incrementFoodLevel(consumable.getFoodValue());
92	            consumable.setEaten();
93	            //System.out.println("EATEN PREY");
94	            return true;
95	        } else {
96	            //System.out.println("LEFT PREY");
97	            return false;
98	        }
99	    }
100	
101	    /**
102	     * Checks all adjacent location for predators that meet specific
103	     * breeding conditions, and returns true if it is even possible.
104	     *
105	     * @return Whether this lion can breed or not.
106	     */
107	    @Override
108	    abstract protected boolean canBreed();
109	
110	    /**
111	     * Increase the predator's food level by a given integer amount.
112	     *
113	     * @param foodLevel The value to increment food level by.
114	     */
115	    public void incrementFoodLevel(int foodLevel) {
116	        this.foodLevel += foodLevel;
117	    }
118	
119	    /**
120	     * Make this predator more hungry. This could result in the predator's death.
121	     */
122	    public void incrementHunger() {
123	        foodLevel--;
124	        if (foodLevel <= 0) {
125	            remove();
126	        }
127	    }
128	}
