3	/**
4	 * This file is part of the Predator-Prey Simulation.
5	 *
6	 * A class for the weather in the simulation.
7	 *
8	 * @version 2022.03.02
9	 */
10	public class Weather {
11	
12	    // define fields
13	    private static final double SUN_PROBABILITY = 0.2;
14	    private static final double RAIN_PROBABILITY = 0.1;
15	    private static final double FOG_PROBABILITY = 0.3;
16	    private static final double SNOW_PROBABILITY = 0.05;
17	    private static final double STORM_PROBABILITY = 0.02;
18	
19	    private static final int MAX_HOURS = 3;
20	
21	    private ArrayList<WeatherType> recentWeather;
22	    private WeatherType type;
23	    private int hours;
24	    private int count;
25	
26	    private static final Random rand = Randomizer.getRandom();
27	
28	    /**
29	     * Constructor for Weather class.
30	     *
31	     * @param initialType Initial given weather.
32	     */
33	    public Weather(WeatherType initialType) {
34	        this.type = initialType;
35	        recentWeather = new ArrayList<>();
36	    }
37	
38	    /**
39	     * Generates the next weather event to produce, on the
40	     * condition one is not already in progress.
41	     */
42	    public void generate() {
43	        if (count != 0) {
44	            count++;
45	            if (count > hours) {
46	                count = 0; // reset
47	            }
48	            return;
49	        }
50	
51	        this.hours = rand.nextInt(MAX_HOURS);
52	
53	        // Switch statements can't be used here due to double accuracy rules.
54	        if (rand.nextDouble() <= SUN_PROBABILITY) {
55	            type = WeatherType.SUN;
56	        } else if (rand.nextDouble() <= RAIN_PROBABILITY) {
57	            type = WeatherType.RAIN;
58	        } else if (rand.nextDouble() <= FOG_PROBABILITY) {
59	            type = WeatherType.FOG;
60	        } else if (rand.nextDouble() <= SNOW_PROBABILITY) {
61	            type = WeatherType.SNOW;
62	        } else if (rand.nextDouble() <= STORM_PROBABILITY) {
63	            type = WeatherType.STORM;
64	        }
65	
66	        //If in the last 4 weathers we had, there was rain or sun, grow at a higher rate.
67	
68	        //Adds to the end of the list,
69	        recentWeather.add(type);
70	
71	        if (recentWeather.size() == 4){
72	            //remove from the start of the list
73	            recentWeather.remove(0);
74	        }
75	        count++;
76	    }
77	
78	    /**
79	     * Returns an ArrayList of the most recent weathers.
80	     * @return ArrayList of most recent weathers.
81	     */
82	    public ArrayList<WeatherType> getRecentWeather() {
83	        return recentWeather;
84	    }
85	
86	    /**
87	     * Get the current type of weather.
88	     * @return Get current weather type.
89	     */
90	    public WeatherType getType() {
91	        return this.type;
92	    }
93	}
