7	 *
8	 * A scavenger animal present in the simulation.
9	 *
10	 * @version 2022.03.02
11	 */
12	public abstract class Scavenger extends Animal {
13	
14	    // define fields
15	    private int foodLevel;
16	
17	    // shared random generator to generate consistent results
18	    private static final Random rand = Randomizer.getRandom();
19	
20	    /**
21	     * Constructor for a scavenger in the simulation.
22	     *
23	     * @param foodLevel The food level of this scavenger.
24	     * @param randomAge Whether the scavenger should have a random age or not.
25	     * @param field The field in which the scavenger resides.
26	     * @param location The location in which the scavenger spawns into.
27	     */
28	    public Scavenger(int foodLevel, boolean randomAge, Field field, Location location) {
29	        super(randomAge, field, location);
30	        this.foodLevel = foodLevel;
31	    }
32	
33	    /**
34	     * Method for what the scavenger does, i.e. what is always run at every step.
35	     *
36	     * @param newScavengers A list of all newborn scavengers in this simulation step.
37	     * @param weather The current state of weather in the simulation.
38	     * @param time The current state of time in the simulation.
39	     */
40	    @Override
41	    public void act(List<Entity> newScavengers, Weather weather, TimeOfDay time) {
42	        incrementAge();
43	        incrementHunger();
44	        if(isAlive()) {
45	            giveBirth(newScavengers);
46	
47	            if (time == TimeOfDay.SUNSET){
48	                return;
49	            }
50	
51	            if (rand.nextDouble() <= getDeathByDiseaseProbability() ) {
52	                remove();
53	                return;
54	            }
55	
56	            // Move towards a source of food if found.
57	            Location newLocation;
58	
59	            if (rand.nextDouble() <= getDiseaseSpreadProbability() ) {
60	                newLocation = findAnimalToInfect();
61	            } else {
62	                newLocation = findFood();
63	            }
64	
65	            if(newLocation == null) {
66	                // No food found - try to move to a free location.
67	                newLocation = getField().freeAdjacentLocation(getLocation());
68	            }
69	
70	            // See if it was possible to move.
71	            if(newLocation != null) {
72	                setLocation(newLocation);
73	            }
74	            else {
75	                // Overcrowding.
76	                //setDead();
77	                remove();
78	            }
79	        }
80	    }
81	
82	    /**
83	     * Find a food source the scavenger would want to eat.
84	     * @return The location of the food source.
85	     */
86	    @Override
87	    public Location findFood() {
88	        Field field = getField();
89	        List<Location> adjacent = field.adjacentLocations(getLocation());
90	        Iterator<Location> it = adjacent.iterator();
91	        while(it.hasNext()) {
92	            Location where = it.next();
93	            Object animal = field.getObjectAt(where);
94	            if (animal instanceof Prey) {
95	                Prey prey = (Prey) animal;
96	                // eats animal if dead only
97	                if (!prey.isAlive()) {
98	                    //System.out.println("EATEN DEAD");
99	                    eat(prey);
100	                    return where;
101	                }
102	            }
103	        }
104	        return null;
105	    }
106	
107	    /**
108	     * Eat the corpse of a dead prey.
109	     *
110	     * @param consumable The item to be eaten.
111	     * @return Whether the consumable was eaten or not.
112	     */
113	    @Override
114	    public boolean eat(Consumable consumable) {
115	        // the scavenger does not leave its prey
116	        consumable.setEaten();
117	        incrementFoodLevel(consumable.getFoodValue());
118	        return true;
119	    }
120	
121	    /**
122	     * Checks all adjacent location for scavengers that meet specific
123	     * breeding conditions, and returns true if it is even possible.
124	     *
125	     * @return Whether this scavenger can breed or not.
126	     */
127	    @Override
128	    abstract public boolean canBreed();
129	
130	    /**
131	     * Increment the food level of this scavenger by a given amount.
132	     *
133	     * @param foodLevel A given food level.
134	     */
135	    public void incrementFoodLevel(int foodLevel) {
136	        this.foodLevel += foodLevel;
137	    }
138	
139	    /**
140	     * Make this scavenger more hungry. This could result in the scavenger's death.
141	     */
142	    public void incrementHunger() {
143	        foodLevel--;
144	        if (foodLevel <= 0) {
145	            remove();
146	        }
147	    }
148	}
