1	import java.util.HashMap;
2	
3	/**
4	 * This class collects and provides some statistical data on the state 
5	 * of a field. It is flexible: it will create and maintain a counter 
6	 * for any class of object that is found within the field.
7	 *
8	 * @version 2016.02.29
9	 */
10	public class FieldStats
11	{
12	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
13	    private HashMap<Class, Counter> counters;
14	    // Whether the counters are currently up to date.
15	    private boolean countsValid;
16	
17	    /**
18	     * Construct a FieldStats object.
19	     */
20	    public FieldStats()
21	    {
22	        // Set up a collection for counters for each type of animal that
23	        // we might find
24	        counters = new HashMap<>();
25	        countsValid = true;
26	    }
27	
28	    /**
29	     * Get details of what is in the field.
30	     * @return A string describing what is in the field.
31	     */
32	    public String getPopulationDetails(Field field)
33	    {
34	        StringBuffer buffer = new StringBuffer();
35	        if(!countsValid) {
36	            generateCounts(field);
37	        }
38	        for(Class key : counters.keySet()) {
39	            Counter info = counters.get(key);
40	            buffer.append(info.getName());
41	            buffer.append(": ");
42	            buffer.append(info.getCount());
43	            buffer.append(' ');
44	        }
45	        return buffer.toString();
46	    }
47	    
48	    /**
49	     * Invalidate the current set of statistics; reset all 
50	     * counts to zero.
51	     */
52	    public void reset()
53	    {
54	        countsValid = false;
55	        for(Class key : counters.keySet()) {
56	            Counter count = counters.get(key);
57	            count.reset();
58	        }
59	    }
60	
61	    /**
62	     * Increment the count for one class of animal.
63	     * @param animalClass The class of animal to increment.
64	     */
65	    public void incrementCount(Class animalClass)
66	    {
67	        Counter count = counters.get(animalClass);
68	        if(count == null) {
69	            // We do not have a counter for this species yet.
70	            // Create one.
71	            count = new Counter(animalClass.getName());
72	            counters.put(animalClass, count);
73	        }
74	        count.increment();
75	    }
76	
77	    /**
78	     * Indicate that an animal count has been completed.
79	     */
80	    public void countFinished()
81	    {
82	        countsValid = true;
83	    }
84	
85	    /**
86	     * Determine whether the simulation is still viable.
87	     * I.e., should it continue to run.
88	     * @return true If there is more than one species alive.
89	     */
90	    public boolean isViable(Field field)
91	    {
92	        // How many counts are non-zero.
93	        int nonZero = 0;
94	        if(!countsValid) {
95	            generateCounts(field);
96	        }
97	        for(Class key : counters.keySet()) {
98	            Counter info = counters.get(key);
99	            if(info.getCount() > 0) {
100	                nonZero++;
101	            }
102	        }
103	        return nonZero > 1;
104	    }
105	    
106	    /**
107	     * Generate counts of the number of foxes and rabbits.
108	     * These are not kept up to date as foxes and rabbits
109	     * are placed in the field, but only when a request
110	     * is made for the information.
111	     * @param field The field to generate the stats for.
112	     */
113	    private void generateCounts(Field field)
114	    {
115	        reset();
116	        for(int row = 0; row < field.getDepth(); row++) {
117	            for(int col = 0; col < field.getWidth(); col++) {
118	                Object animal = field.getObjectAt(row, col);
119	                if(animal != null) {
120	                    incrementCount(animal.getClass());
121	                }
122	            }
123	        }
124	        countsValid = true;
125	    }
126	}
